\set ON_ERROR_STOP on
reset role;
create function test.vote_rejects(statement text, expected_state text) returns void language plpgsql as $$
begin
 begin execute statement; exception when others then if sqlstate=expected_state then return; end if; raise; end;
 raise exception 'Expected rejection %',expected_state;
end $$;
grant execute on function test.vote_rejects(text,text) to anon,authenticated,service_role;
delete from public.rounds;
set role service_role;
select public.live_create_round('11111111-1111-4111-8111-111111111111','exhibition',array['rules'],repeat('a',64),repeat('b',64),'{"schemaVersion":"recovery-1","workerVersion":"rules-worker-1","votingEnabled":false}',true);
select public.live_acquire_lease('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',60);
select test.vote_rejects($q$select public.live_open_vote_window('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1)$q$,'PT409');
reset role;
-- Test-only boundary seeding, before enabling the deliberate worker integration guard.
update public.rounds set tick=30,sequence=31 where id='11111111-1111-4111-8111-111111111111';
update live_private.round_state set recovery=recovery || '{"votingEnabled":true}' where round_id='11111111-1111-4111-8111-111111111111';
set role service_role;
select test.vote_rejects($q$select public.live_open_vote_window('11111111-1111-4111-8111-111111111111','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1)$q$,'55000');
select test.assert(public.live_open_vote_window('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1)->>'status'='open','fenced open');
reset role;
create temp table first_window as select * from live_private.vote_windows;
set role service_role;
select public.live_open_vote_window('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1);
reset role;
select test.assert((select w.deadline_ms=f.deadline_ms from live_private.vote_windows w join first_window f using(round_id)),'open retry preserves deadline');
set role anon;
select test.assert(public.live_get_vote_window('11111111-1111-4111-8111-111111111111')->>'status'='open','public reads sanitized window');
select test.vote_rejects('select * from live_private.vote_windows','42501');
select test.vote_rejects($q$select public.live_submit_vote('11111111-1111-4111-8111-111111111111','cccccccc-cccc-4ccc-8ccc-cccccccccccc','00000000-0000-4000-8000-000000000001','rain')$q$,'42501');
set role authenticated;
select test.vote_rejects($q$select public.live_get_vote_receipt('11111111-1111-4111-8111-111111111111','cccccccc-cccc-4ccc-8ccc-cccccccccccc')$q$,'42501');
set role service_role;
select test.vote_rejects('select * from live_private.vote_receipts','42501');
select test.assert(public.live_submit_vote('11111111-1111-4111-8111-111111111111','cccccccc-cccc-4ccc-8ccc-cccccccccccc','00000000-0000-4000-8000-000000000001','rain')->>'replayed'='false','first receipt');
select test.assert(public.live_submit_vote('11111111-1111-4111-8111-111111111111','cccccccc-cccc-4ccc-8ccc-cccccccccccc','00000000-0000-4000-8000-000000000002','bus')->>'replayed'='false','changed selection');
select test.assert(public.live_submit_vote('11111111-1111-4111-8111-111111111111','cccccccc-cccc-4ccc-8ccc-cccccccccccc','00000000-0000-4000-8000-000000000001','rain')->>'replayed'='true','retry original receipt');
select test.assert(public.live_get_vote_receipt('11111111-1111-4111-8111-111111111111','cccccccc-cccc-4ccc-8ccc-cccccccccccc')->>'option_id'='bus','old retry never restores stale selection');
select test.assert(public.live_get_vote_window('11111111-1111-4111-8111-111111111111')->'counts'='{"bus":1,"rain":0,"supplier-delay":0}'::jsonb,'one current selection');
select test.vote_rejects($q$select public.live_submit_vote('11111111-1111-4111-8111-111111111111','cccccccc-cccc-4ccc-8ccc-cccccccccccc','00000000-0000-4000-8000-000000000001','bus')$q$,'PT409');
select test.vote_rejects($q$select public.live_submit_vote('11111111-1111-4111-8111-111111111111','cccccccc-cccc-4ccc-8ccc-cccccccccccc','00000000-0000-4000-8000-000000000003','bus')$q$,'PT429');
select public.live_control_round('11111111-1111-4111-8111-111111111111','00000000-0000-4000-8000-000000000101','pause',0,'operator-test');
select test.assert(public.live_get_vote_window('11111111-1111-4111-8111-111111111111')->>'paused'='true','pause visible');
select test.vote_rejects($q$select public.live_submit_vote('11111111-1111-4111-8111-111111111111','dddddddd-dddd-4ddd-8ddd-dddddddddddd','00000000-0000-4000-8000-000000000003','rain')$q$,'PT409');
reset role;
create temp table paused_window as select * from live_private.vote_windows;
select pg_sleep(0.02);
select test.assert((select w.remaining_ms=p.remaining_ms and w.deadline_ms is null from live_private.vote_windows w join paused_window p using(round_id)),'paused duration remains durable');
set role service_role;
select public.live_control_round('11111111-1111-4111-8111-111111111111','00000000-0000-4000-8000-000000000102','resume',1,'operator-test');
reset role;
select test.assert((select w.deadline_ms>=floor(extract(epoch from clock_timestamp())*1000)::bigint+p.remaining_ms-1000 from live_private.vote_windows w join paused_window p using(round_id)),'resume restores remaining duration');
select test.vote_rejects('update public.rounds set tick=31,sequence=32','55000');
-- Strict elapsed deadline rejects new requests, but accepted retries remain available.
update live_private.vote_windows set deadline_ms=floor(extract(epoch from clock_timestamp())*1000)::bigint;
set role service_role;
select test.assert(public.live_get_vote_window('11111111-1111-4111-8111-111111111111')->>'status'='locked','deadline locked without worker');
select test.vote_rejects($q$select public.live_submit_vote('11111111-1111-4111-8111-111111111111','dddddddd-dddd-4ddd-8ddd-dddddddddddd','00000000-0000-4000-8000-000000000003','rain')$q$,'PT409');
select public.live_control_round('11111111-1111-4111-8111-111111111111','00000000-0000-4000-8000-000000000103','pause',2,'operator-test');
select public.live_control_round('11111111-1111-4111-8111-111111111111','00000000-0000-4000-8000-000000000104','resume',3,'operator-test');
select test.assert(public.live_get_vote_window('11111111-1111-4111-8111-111111111111')->>'status'='locked','pause after deadline never reopens');
select public.live_control_round('11111111-1111-4111-8111-111111111111','00000000-0000-4000-8000-000000000105','stop',4,'operator-test');
select test.assert(public.live_get_vote_window('11111111-1111-4111-8111-111111111111')->>'status'='disabled','stop disables');
select test.assert(public.live_submit_vote('11111111-1111-4111-8111-111111111111','cccccccc-cccc-4ccc-8ccc-cccccccccccc','00000000-0000-4000-8000-000000000001','rain')->>'replayed'='true','accepted retry survives stop');
reset role;
update public.rounds set published=false;
set role anon;
select test.assert(public.live_get_vote_window('11111111-1111-4111-8111-111111111111') is null,'private window hidden');
reset role;
-- Bounded durable quotas. Seed only test-owned rows to isolate limits without sleeps.
update public.rounds set published=true,control_state='active';
update live_private.vote_windows set status='open',paused=false,deadline_ms=floor(extract(epoch from clock_timestamp())*1000)::bigint+20000,remaining_ms=20000;
delete from live_private.vote_receipts;
insert into live_private.vote_receipts select '11111111-1111-4111-8111-111111111111',('00000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,('10000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'rain',floor(extract(epoch from clock_timestamp())*1000)::bigint from generate_series(1,20) i;
set role service_role;
select test.vote_rejects($q$select public.live_submit_vote('11111111-1111-4111-8111-111111111111','dddddddd-dddd-4ddd-8ddd-dddddddddddd','00000000-0000-4000-8000-000000000003','rain')$q$,'PT429');
reset role;
update live_private.vote_receipts set accepted_at_ms=accepted_at_ms-2000;
insert into live_private.vote_receipts select '11111111-1111-4111-8111-111111111111','dddddddd-dddd-4ddd-8ddd-dddddddddddd',('20000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'rain',1 from generate_series(1,20) i;
set role service_role;
select test.vote_rejects($q$select public.live_submit_vote('11111111-1111-4111-8111-111111111111','dddddddd-dddd-4ddd-8ddd-dddddddddddd','00000000-0000-4000-8000-000000000003','rain')$q$,'PT429');
reset role;
insert into live_private.vote_receipts select '11111111-1111-4111-8111-111111111111',('30000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,('30000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'rain',1 from generate_series(1,360) i;
set role service_role;
select test.vote_rejects($q$select public.live_submit_vote('11111111-1111-4111-8111-111111111111','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','00000000-0000-4000-8000-000000000003','rain')$q$,'PT429');
reset role;
select 'Durable vote lifecycle, privacy, limits and fail-closed worker gate passed.';
